<!--vbase-->
<template>
  <q-btn
    flat
    dense
    id="ignore_table_validation"
    class="icon-grey validation-footer-table-button"
    @click="ignoreTableValidation"
  >
    <Icon :icon="ignore_table_validation ? 'mdi:table-check' : 'mdi:table-off'" width="20" height="20" />
    <q-tooltip>{{ $t('ignore_table_validation') }}</q-tooltip>
  </q-btn>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { useDocumentStore, useFormBuilderStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
  },
  data() {
    return {};
  },
  mounted() {
    //  mout event listeners
    this.init();
  },
  methods: {
    init() {
      if (this.isFormBuilderMode) {
        return;
      }

      this.ignore_table_validation = this.record.ignore_table_validation == true;
    },
    ignoreTableValidation() {
      if (this.isFormBuilderMode || this.isReadOnly) {
        return;
      }
      this.ignore_table_validation = !this.ignore_table_validation;

      if (!this.ignore_table_validation) {
        delete this.record.ignore_table_validation;
        return;
      }

      this.record.ignore_table_validation = this.ignore_table_validation;
    },
  },
  setup() {
    const doc_store = useDocumentStore();
    const { doc_loaded, record } = storeToRefs(doc_store);

    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode } = storeToRefs(form_builder_store);

    return {
      isFormBuilderMode,
      doc_loaded,
      record,
      ignore_table_validation: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.block-icon {
  padding: 0px !important;
  padding-bottom: 4px !important;
}
</style>
